/** A saved weekly digest (90_Digests) in the review's digest list. */
export interface ReviewDigest {
  id: string;
  title: string;
  group: string;
  /** "Week 43/2026" */
  week: string;
  periodStart: string | null;
  headline: string | null;
}

export interface ReviewFocus {
  t: string;
  area: string;
  on: boolean;
  /** Live: the focus point is this open task (else a task is created on save). */
  taskId?: string;
}

/** Everything the review renders; the mock below is one instance, live data comes from lib/data/review.ts. */
export interface ReviewData {
  review: typeof REVIEW & { isoWeek: string };
  stats: { v: string; l: string }[];
  highlights: { t: string; id: string }[];
  /** Open tasks of the week; `id` = action_items id (live) to move into next week. */
  open: { k: string; t: string; id?: string }[];
  balance: [string, number, number][];
  questions: [question: string, hint: string][];
  focus: ReviewFocus[];
  week: { d: string; items: { t: string; cls: string }[] }[];
  digests: ReviewDigest[];
  /** A review note for this week exists already. */
  saved: boolean;
}

